<?php
if ( php_sapi_name() !== 'cli' ) { exit; }
// Restaura wp-content/plugins/homvuk-portal/homvuk-portal.php (version 1.4.2 original)
$b64 = '';
$data = base64_decode( $b64 );
if ( strpos( $data, "define( 'HVKP_VERSION', '1.4.2' )" ) === false || strpos( $data, '<?php' ) !== 0 ) {
    echo "ERROR: contenido invalido\n";
    exit( 1 );
}
$target = __DIR__ . '/wp-content/plugins/homvuk-portal/homvuk-portal.php';
file_put_contents( $target, $data );
$out = shell_exec( 'php -l ' . escapeshellarg( $target ) . ' 2>&1' );
echo "Restaurado (" . round( strlen( $data ) / 1024 ) . " KB): " . trim( (string) $out ) . "\n";
echo "== PORTAL RESTAURADO ==\n";
